
import type { CreditNoteLine } from './CreditNoteLine.js';
import type { DocumentTaxID } from './DocumentTaxID.js';
import type { MoneyValue } from './MoneyValue.js';

/** The buyer-visible view of a credit note. Drafts are never returned, and how much credit is left to allocate is omitted. */ export type BuyerCreditNote = { /** Identity frozen on the source invoice at issue. Later profile edits do not change this document. */ "buyer_tax_identity"?: (({ /** minLength: 1. maxLength: 255. */ "legal_name"?: string | null; "registered_address"?: (({ "city": string; /** ISO 3166-1 alpha-2 country code. minLength: 2. maxLength: 2. pattern: ^[A-Z]{2}$. Example: "US". */ "country": string; "line1": string; "line2"?: string; "postal_code": string; "state": string; }) | (null)); /** maxItems: 20. */ "tax_ids": Array<DocumentTaxID>; }) | (null)); "credit_note_id": string; "credit_note_lines": Array<CreditNoteLine>; /** Assigned at issue and stable from then on. Absent while the credit note is a draft. */ "credit_note_number": string; "invoice_id": string; /** RFC3339 timestamp. Format: date-time. */ "issued_at": string; "latest_refund_status"?: "pending" | "in_transit" | "succeeded" | "failed" | "requires_action" | "canceled" | "partially_succeeded" | (string & {}); "memo"?: string; "pending_refund_money": MoneyValue; /** Why the invoice is being corrected. Shown on the credit note document. */ "reason": "returned_goods" | "order_adjustment" | "billing_error" | "goodwill" | "other" | (string & {}); "refunded_money": MoneyValue; /** Identity frozen on the source invoice at issue. Later profile edits do not change this document. */ "seller_tax_identity"?: (({ /** minLength: 1. maxLength: 255. */ "legal_name"?: string | null; "registered_address"?: (({ "city": string; /** ISO 3166-1 alpha-2 country code. minLength: 2. maxLength: 2. pattern: ^[A-Z]{2}$. Example: "US". */ "country": string; "line1": string; "line2"?: string; "postal_code": string; "state": string; }) | (null)); /** maxItems: 20. */ "tax_ids": Array<DocumentTaxID>; }) | (null)); /** draft while the credit note is editable, issued once it is numbered and frozen, void once retired. */ "status": "issued" | "void" | (string & {}); /** The face value of the credit note, the sum of its lines. */ "total_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** RFC3339 timestamp. Format: date-time. */ "voided_at"?: string; };
